/* MTST10 ($FC1C) - TEST 10 - TEST BLOCK INDEX COUNTER
 *   LDA X,IND,CLA
 *   LDB ZERO
 *   LDC ONE,MAC
 *   SAC XP,HALT
 * Condition codes out: NZVC.
 */
void mtst10(void)
{
    CK(0xFC1C);
    U = (MBRAM+0x28);                                /* LFC1C  SETUP THE MATH RAM */
    D = 0x0005;                                      /* LFC1F  START AT BIC #4 */
    CYC(6);
    do {
        CK(0xFC22);
        wr16(U, D);                                  /* LFC22 */
        D = (uint16_t)(D + 0x0001);                  /* LFC24 */
        U = (uint16_t)(U + 8);                       /* LFC27 */
        CYC(22);
    } while (U < MBRAMZ);                            /* LFC2D  HSEND   */
    D = 0x0000;                                      /* LFC2F */
    wr16(M_ZRO, D);                                  /* LFC32 */
    D = 0x4000;                                      /* LFC35 */
    wr16(M_ONE, D);                                  /* LFC38 */
    D = 0x0004;                                      /* LFC3B */
    CYC(21);
    hw_wr16(M_BIC, D);                               /* LFC3E */
    U = 0x0008;                                      /* LFC41  START AT 8TH BIC */
    CYC(9);
    do {
        CK(0xFC44);
        hw_wr8(WTCHDG, A);                           /* LFC44 */
        D = U;                                       /* LFC47  INCREMENT THE BIC */
        A = lsr8(A);                                 /* LFC49  LSRD  ADD HALF THE CURRENT VALUE OF U */
        B = ror8(B);                                 /* LFC4A  LSRD  ADD HALF THE CURRENT VALUE OF U */
        CYC(15);
        do {
            CK(0xFC4B);
            A = 0x5B;                                /* LFC4B  INC BIC */
            CYC(2);
            hw_wr8(M_PCGO, A);                       /* LFC4D */
            B = (uint8_t)(B - 1);                    /* LFC50 */
            CYC(10);
        } while (B != 0);                            /* LFC51  EQEND   */
        A = 0x5F;                                    /* LFC53  GO GET THE DATA */
        CYC(2);
        hw_wr8(M_PCGO, A);                           /* LFC55 */
        D = (uint16_t)(A * B);                       /* LFC58 */
        cmp16(U, rd16(M_XP));                        /* LFC59  SHOULD BE THE SAME */
        CYC(27);
        if (!CCZ) {                                  /* LFC5D  IFNE  ERROR */
            CYC(4);
            tdivz(); return;                         /* LFC5F */
        }
        D = U;                                       /* LFC62  ADD U TO ITSELF */
        U = (uint16_t)(U + D);                       /* LFC64 */
        cmp16(U, 0x0200);                            /* LFC66 */
        CYC(22);
    } while (CCC);                                   /* LFC6A  HSEND   */
    D = 0x0000;                                      /* LFC6C  NO ERRORS */
    nz16(D);
    CYC(7);
    tdivz(); return;                                 /* LFC6F */
}

