/* MTST12 ($FCAC) - TEST 12 LOOP -- TESTS SUBTRACT
 *   LDA XT,CLA
 *   LDB YT
 *   LDC ZT,MAC
 *   SAC XP,HALT
 *   B MUST BE SET TO 0,2,4 OR 6 BEFORE GETTING HERE
 * Condition codes out: NZVC.
 */
void mtst12(void)
{
    CK(0xFCAC);
    B = (uint8_t)(B << 1);                           /* LFCAC */
    B = (uint8_t)(B << 1);                           /* LFCAD */
    U = TMTRX;                                       /* LFCAE  TABLE OF VALUES FOR TEST 12 */
    U = (uint16_t)(U + (int8_t)B);                   /* LFCB1 */
    D = rd16(U);                                     /* LFCB3 */
    wr16(M_XT, D);                                   /* LFCB5 */
    D = rd16((uint16_t)(U + 2));                     /* LFCB8 */
    wr16(M_YT, D);                                   /* LFCBA */
    D = rd16((uint16_t)(U + 4));                     /* LFCBD */
    wr16(M_ZT, D);                                   /* LFCBF */
    A = 0x5D;                                        /* LFCC2 */
    CYC(49);
    hw_wr8(M_PCGO, A);                               /* LFCC4 */
    D = (uint16_t)(A * B);                           /* LFCC7  DELAY */
    D = rd16(M_XP);                                  /* LFCC8 */
    cmp16(D, rd16((uint16_t)(U + 6)));               /* LFCCB */
    CYC(34);
    tdivz(); return;                                 /* LFCCE */
}

/* TMULZ ($FD07) - GO EXECUTE DIAGNOSTICS, NOW WITHOUT DELAY
 * Condition codes out: NZVC.
 */
void tmulz(void)
{
    uint8_t t8;
    CK(0xFD07);
    A = hw_rd8(TESTSW);                              /* LFD07  BOTH TEST AND DIAG SWITCHES ON? */
    A &= TESTBT;                                     /* LFD0A */
    CYC(7);
    B = hw_rd8(DIAGSW);                              /* LFD0C */
    B &= DIAGBT;                                     /* LFD0F */
    /* CMPD 0x0000 */                                /* LFD11  SHOULD BE 0000 IF BOTH ON */
    CYC(15);
    if (D != 0x0000) {                               /* LFD15  IFNE   */
        CYC(4);
        hang(); return;                              /* LFD17  WAIT FOR WATCH DOG */
    }
    hw_wr8(WTCHDG, A);                               /* LFD1A  KEEP THE DOG QUIET */
    A = 0xFF;                                        /* LFD1D  TURN OFF ALL LEDS */
    CYC(7);
    hw_wr8(W_LED1, A);                               /* LFD1F */
    CYC(5);
    hw_wr8(W_LED2, A);                               /* LFD22 */
    CYC(5);
    hw_wr8(W_LED3, A);                               /* LFD25 */
    CYC(5);
    B = hw_rd8(R_BYT2);                              /* LFD28 */
    B = (uint8_t)~B;                                 /* LFD2B */
    U = TDNUM;                                       /* LFD2C  TABLE OF DIAG NUM TO BCD CONVERSIONS */
    CYC(10);
    do {
        CK(0xFD2F);
        t8 = rd8(U);                                 /* LFD2F  IS THIS THE SWITCH CONFIGURATION? */
        U = (uint16_t)(U + 1);
        CYC(9);
        if (B == t8) {                               /* LFD31  IFEQ  YES, THEN SHOW THE TEST NUMBER */
            hw_wr8(VGSTOP, A);                       /* LFD33  MAKE SURE VG HAS STOPPED */
            Y = VGRAM;                               /* LFD36  SET UP POINTER */
            D = VJBONDRY;                            /* LFD3A  DRAW A BOX */
            wr16(Y, D);                              /* LFD3D */
            Y = (uint16_t)(Y + 2);
            D = VGCNTR;                              /* LFD3F */
            wr16(Y, D);                              /* LFD42 */
            Y = (uint16_t)(Y + 2);
            A = rd8(U);                              /* LFD44  GET BCD FOR DIAG NUMBER */
            S = STACK;                               /* LFD46 */
            CYC(47);
            JSR(vwbyte);                             /* LFD4A */
            D = 0x2020;                              /* LFD4D  PUT A HALT IN AT END OF LIST */
            wr16(Y, D);                              /* LFD50 */
            Y = (uint16_t)(Y + 2);
            wr16(Y, D);                              /* LFD52 */
            Y = (uint16_t)(Y + 2);
            CYC(19);
            hw_wr8(VGGO, A);                         /* LFD54  START THE VG */
            U = TDNUMZ;                              /* LFD57  LEAVE THE LOOP */
            CYC(8);
        }
        U = (uint16_t)(U + 1);                       /* LFD5A  NEXT ENTRY */
        CYC(13);
    } while (U < TDNUMZ);                            /* LFD60  HSEND   */
    B = hw_rd8(R_BYT2);                              /* LFD62  READ OPTION SWITCH TO FIND DIAGNOSTIC TEST # */
    B = (uint8_t)~B;                                 /* LFD65  OFF-->0, ON-->1 */
    A = B;                                           /* LFD66 */
    B &= 0x0F;                                       /* LFD68  TO BE USED BY CERTAIN TESTS INTERNALLY */
    A &= 0xF8;                                       /* LFD6A  TOP 5 BITS INDICATE TEST TYPE */
    /* CMPA 0xC0 */                                  /* LFD6C  AVG INSTRUCTIONS? */
    CYC(22);
    if (A != 0xC0) {                                 /* LFD6E  IFNE  NO */
        M8(SIGFLG) = 0;                              /* LFD70  MAKE SURE SIGNATURE ANALYSIS GETS INITIATED CORRECTLY */
        CYC(6);
    }
    X = TDIAG;                                       /* LFD72 */
    CYC(3);
    do {
        CK(0xFD75);
        cmp8(A, rd8(X));                             /* LFD75 */
        X = (uint16_t)(X + 1);
        CYC(9);
        if (CCZ) {                                   /* LFD77  IFEQ   */
            CYC(6);
            call_rom(rd16(X)); return;               /* LFD79 */
        }
        X = (uint16_t)(X + 2);                       /* LFD7B */
        /* CMPX TDIAGZ */                            /* LFD7D  PAST END OF TABLE? */
        CYC(12);
    } while (X < TDIAGZ);                            /* LFD80  HSEND  IF NOT KEEP LOOKING */
    CYC(4);
    diagerr(); return;                               /* LFD82  ELSE FLASH ALL 3 LEDS TO INDICATE ERROR */
}

/* TDNUMZ ($FDBC) - KERNAL TEST
 * Condition codes out: NZVC.
 */
void tdnumz(void)
{
    CK(0xFDBC);
    /* TSTB */                                       /* LFDBC  SHOULD BE 00 */
    CYC(5);
    if (B != 0) {                                    /* LFDBD  IFNE  ERROR */
        CYC(4);
        diagerr(); return;                           /* LFDBF */
    }
    D = S;                                           /* LFDC2  GET TEST RESULTS */
    A &= 0x40;                                       /* LFDC4  ROM 4 OK? */
    B &= 0x01;                                       /* LFDC6  RAM OK? */
    CYC(18);
    if (D == 0x0000) {                               /* LFDCC  IFEQ  YES, ROM AND RAM OK */
        U = W_LED1;                                  /* LFDCE  THEN FLASH LED 1 */
        CYC(7);
        ledflsh(); return;                           /* LFDD1  AND RETURN TO DIAGLP */
    }
    CYC(4);
    tmulz(); return;                                 /* LFDD4 */
}

/* D_AVGR ($FDD7) - AVG RAM AND ROM TEST
 * Condition codes out: NZVC.
 */
void d_avgr(void)
{
    CK(0xFDD7);
    /* TSTB */                                       /* LFDD7  SHOULD BE 00 */
    CYC(5);
    if (B != 0) {                                    /* LFDD8  IFNE  ERROR */
        CYC(4);
        diagerr(); return;                           /* LFDDA */
    }
    D = S;                                           /* LFDDD */
    A &= 0x81;                                       /* LFDDF */
    B &= 0xF8;                                       /* LFDE1 */
    CYC(18);
    if (D == 0x0000) {                               /* LFDE7  IFEQ  AVG RAM AND ROM ARE OK */
        U = W_LED2;                                  /* LFDE9  THEN FLASH LED 2 */
        CYC(7);
        ledflsh(); return;                           /* LFDEC  AND RETURN TO DIAGLP */
    }
    CYC(4);
    tmulz(); return;                                 /* LFDEF */
}

/* D_AVGI ($FDF2) - AVG INSTRUCTIONS
 * Condition codes out: NZVC.
 */
void d_avgi(void)
{
    CK(0xFDF2);
    /* CMPB 0x06 */                                  /* LFDF2  SIGNATURE ANALYSIS? */
    CYC(5);
    if (B == 0x06) {                                 /* LFDF4  IFEQ  YEP */
        /* TST SIGFLG */                             /* LFDF6  BEEN THROUGH HERE ALREADY? */
        CYC(9);
        if (M8(SIGFLG) == 0) {                       /* LFDF8  IFEQ  NOPE, THEN SET UP RAM, AND SET FLAG */
            X = (VGRAM+0x800);                       /* LFDFA  VGRAM1 */
            A = 0x00;                                /* LFDFD */
            CYC(5);
            do {
                CK(0xFDFF);
                wr8(X, A);                           /* LFDFF */
                X = (uint16_t)(X + 1);
                A = (uint8_t)(A + 0x05);             /* LFE01 */
                /* CMPX (VGRAM+0x1000) */            /* LFE03  FILLED VGRAM1 WITH APPROPRIATE DATA? */
                CYC(15);
            } while (X < (VGRAM+0x1000));            /* LFE06  HSEND   */
            A = 0xFF;                                /* LFE08 */
            M8(SIGFLG) = A;                          /* LFE0A  FLAG SO WON'T DO IT AGAIN */
            CYC(6);
        }
        CYC(3);
    } else {                                         /* LFE0C  ELSE  NORMAL AVG INSTRUCTIONS */
        M8(SIGFLG) = 0;                              /* LFE0E */
        CYC(6);
        hw_wr8(VGSTOP, A);                           /* LFE10 */
        X = TAVGI;                                   /* LFE13 */
        B = (uint8_t)(B << 1);                       /* LFE16  2-WORD ENTRIES */
        B = (uint8_t)(B << 1);                       /* LFE17 */
        X = (uint16_t)(X + B);                       /* LFE18 */
        CYC(22);
        if (X >= TAVGIZ) {                           /* LFE1C  IFHS   */
            CYC(4);
            diagerr(); return;                       /* LFE1E  FLASH LEDS */
        }
        D = rd16(X);                                 /* LFE21  SET UP INSTRUCTIONS FROM THE TABLE */
        wr16(VGRAM+0, D);                            /* LFE23 */
        D = rd16((uint16_t)(X + 2));                 /* LFE26 */
        wr16(VGRAM+2, D);                            /* LFE28 */
        D = 0x2020;                                  /* LFE2B  MAKE SURE IT STOPS */
        wr16(VGRAM+4, D);                            /* LFE2E */
        CYC(32);
        hw_wr8(VGGO, A);                             /* LFE31  START THE VG */
        CYC(5);
    }
    CYC(4);
    tmulz(); return;                                 /* LFE34  GO BACK TO THE DIAGNOSTIC MAIN LOOP */
}

/* TAVGIZ ($FE4F) - MATRIX PROCESSOR INSTRUCTIONS
 * Condition codes out: NZVC.
 */
void tavgiz(void)
{
    CK(0xFE4F);
    X = TMUL;                                        /* LFE4F  MATRIX MULTIPLIER TEST TABLE */
    B = (uint8_t)(B << 1);                           /* LFE52 */
    X = (uint16_t)(X + B);                           /* LFE53 */
    Y = 0x0000;                                      /* LFE54  SETUP REPEAT COUNT */
    CYC(12);
    d_mtrx_30();                                     /* falls into D_MTRX_30 */
}

/* D_MTRX_30 ($FE58)
 * Condition codes out: NZVC.
 */
void d_mtrx_30(void)
{
    CK(0xFE58);
    /* CMPX TMULZ */                                 /* LFE58  PAST END OF TABLE? */
    CYC(7);
    if (X >= TMULZ) {                                /* LFE5B  IFHS  YES */
        CYC(4);
        diagerr(); return;                           /* LFE5D  THEN INDICATE AN ERROR */
    }
    hw_wr8(WTCHDG, A);                               /* LFE60  DOING MULTIPLE TESTS, SO KEEP THE DOG QUIET */
    Y = (uint16_t)(Y + 1);                           /* LFE63  INC REPEAT COUNT */
    CYC(18);
    if (Y >= 0x0200) {                               /* LFE69  IFHS  CHECK FOR NEW TEST, RESTART VG, ETC. */
        S = DLOOP;                                   /* LFE6B  RETURN TO THE DIAGNOSTIC MAIN LOOP DELAY */
        CYC(7);
    } else {                                         /* LFE6F  ELSE  JUST KEEP DOING OLD TEST */
        S = 0xFE58;                                  /* LFE71  RETURN TO ABOVE */
        CYC(4);
    }
    D = X;                                           /* LFE75  SETUP FOR MTST12 */
    D = sub16(D, TMUL1);                             /* LFE77  GIVES 0,2,4 OR 6 */
    CYC(16);
    call_rom(rd16(X)); return;                       /* LFE7A  DO IT AND RETURN VIA S */
}

/* D_DVDR ($FE7C) - DIVIDER TESTS
 * Condition codes out: NZVC.
 */
void d_dvdr(void)
{
    CK(0xFE7C);
    X = TDIV;                                        /* LFE7C  DIVIDER TEST TABLE */
    B = (uint8_t)(B << 1);                           /* LFE7F  8 BYTES PER ENTRY */
    B = (uint8_t)(B << 1);                           /* LFE80 */
    B = (uint8_t)(B << 1);                           /* LFE81 */
    X = (uint16_t)(X + B);                           /* LFE82 */
    Y = 0x0000;                                      /* LFE83  SETUP REPEAT COUNT */
    CYC(16);
    d_dvdr_30();                                     /* falls into D_DVDR_30 */
}

/* D_DVDR_30 ($FE87)
 * Condition codes out: NZVC.
 */
void d_dvdr_30(void)
{
    CK(0xFE87);
    /* CMPX TDIVZ */                                 /* LFE87  PAST END OF TABLE? */
    CYC(7);
    if (X >= TDIVZ) {                                /* LFE8A  IFHS  YES */
        CYC(4);
        diagerr(); return;                           /* LFE8C  THEN INDICATE AN ERROR */
    }
    hw_wr8(WTCHDG, A);                               /* LFE8F  DOING MULTIPLE TESTS, SO KEEP THE DOG QUIET */
    Y = (uint16_t)(Y + 1);                           /* LFE92  INC REPEAT COUNT */
    CYC(18);
    if (Y >= 0x0200) {                               /* LFE98  IFHS  CHECK FOR NEW TEST, RESTART VG, ETC. */
        S = DLOOP;                                   /* LFE9A  RETURN TO THE DIAGNOSTIC MAIN LOOP DELAY */
        CYC(7);
    } else {                                         /* LFE9E  ELSE  JUST KEEP DOING OLD TEST */
        S = 0xFE87;                                  /* LFEA0  RETURN TO ABOVE */
        CYC(4);
    }
    CYC(4);
    divtst(); return;                                /* LFEA4  GO DO IT AND RETURN VIA S */
}

/* D_SND ($FEA7) - SOUND BOARD COMMUNICATIONS
 * Condition codes out: NZVC.
 */
void d_snd(void)
{
    uint8_t t8;
    CK(0xFEA7);
    B &= 0x07;                                       /* LFEA7 */
    CYC(5);
    if (B != 0) {                                    /* LFEA9  IFNE   */
        CYC(4);
        diagerr(); return;                           /* LFEAB */
    }
    A = 0x01;                                        /* LFEAE  STARTING PATTERN */
    CYC(2);
    do {
        CK(0xFEB0);
        hw_wr8(W_RSTS, B);                           /* LFEB0  RESET THE SOUND BOARD (INITIATE PORT TEST) */
        U = X;                                       /* LFEB3  SHORT PAUSE */
        CYC(11);
        B = hw_rd8(R_RCVS);                          /* LFEB5  READ PORT FROM SOUND BOARD, SHOULD CLEAR RECIEVED FLAG */
        CYC(5);
        B = hw_rd8(R_STAS);                          /* LFEB8  CHECK RECEIVE STATUS, SHOULD BE LOW SINCE I JUST READ IT */
        B &= 0x40;                                   /* LFEBB */
        CYC(10);
        if (B != 0) { wait1(); return; }             /* LFEBD  WASN'T CORRECT POLARITY */
        /* CHECK TO SEE IF XMIT READY */
        B = 0x80;                                    /* LFEBF  ALLOW A DELAY */
        CYC(2);
        do {
            CK(0xFEC1);
            B = (uint8_t)(B - 1);                    /* LFEC1 */
            CYC(5);
            if ((B & 0x80)) { wait1(); return; }     /* LFEC2  DELAYED TOO LONG, WAIT A WHILE AND TRY AGAIN */
            hw_wr8(WTCHDG, A);                       /* LFEC4  KEEP THE POOCH QUIET */
            CYC(5);
            t8 = hw_rd8(R_STAS);                     /* LFEC7  CHECK XMIT STATUS */
            CYC(10);
        } while ((t8 & 0x80));                       /* LFECA  PLEND  XMIT IS NOW READY */
        hw_wr8(W_XMTS, A);                           /* LFECC  GIVE THE SOUND BOARD THE DATA PATTERN */
        CYC(5);
        B = hw_rd8(R_STAS);                          /* LFECF  CHECK XMIT STATUS, SHOULD BE HI SINCE I JUST SENT DATA */
        CYC(8);
        if (!(B & 0x80)) { wait1(); return; }        /* LFED2  WRONG, DELAY AND TRY AGAIN LATER */
        /* WAIT FOR SOUND BOARD TO TALK TO US */
        X = 0x0100;                                  /* LFED4  ALLOW A DELAY */
        CYC(3);
        do {
            CK(0xFED7);
            X = (uint16_t)(X - 1);                   /* LFED7 */
            CYC(8);
            if (X == 0) { wait1(); return; }         /* LFED9  DELAYED TOO LONG, TRY AGAIN LATER */
            hw_wr8(WTCHDG, A);                       /* LFEDB */
            CYC(5);
            B = hw_rd8(R_STAS);                      /* LFEDE  GET STATUS */
            B &= 0x40;                               /* LFEE1  HI IF SOUND BOARD TALKED TO US */
            CYC(10);
        } while (B == 0);                            /* LFEE3  NEEND  IT SPOKE! */
        /* THE XMIT LINE SHOULD BE READY AGAIN SINCE IT READ BEFORE IT SPOKE */
        t8 = hw_rd8(R_STAS);                         /* LFEE5 */
        CYC(10);
        if ((t8 & 0x80)) { wait1(); return; }        /* LFEE8  WRONG! DELAY AND TRY AGAIN */
        t8 = hw_rd8(R_RCVS);                         /* LFEEA  COMPARE DATA RCVD FROM SOUND BOARD TO DATA XMITD */
        CYC(8);
        if (A != t8) { wait1(); return; }            /* LFEED  ERROR, GO AWAY AGAIN */
        /* CHECK RECEIVE STATUS AGAIN */
        B = hw_rd8(R_STAS);                          /* LFEEF */
        B &= 0x40;                                   /* LFEF2 */
        CYC(10);
        if ((B & 0x80)) { wait1(); return; }         /* LFEF4  WRONGO */
        A = asl8(A);                                 /* LFEF6  NEW PATTERN */
        CYC(5);
    } while (!CCC);                                  /* LFEF7  CSEND  WHEN BIT SHIFTS TO CARRY, ALL DONE */
    U = W_LED3;                                      /* LFEF9  ELSE ALL OK, FLASH LED #3 */
    CYC(7);
    ledflsh(); return;                               /* LFEFC */
}

/* LEDFLSH ($FEFF) - AND RETURN TO DIAGLP
 * Condition codes out: NZVC.
 */
void ledflsh(void)
{
    CK(0xFEFF);
    A = 0x00;                                        /* LFEFF  TURN LED ON */
    CYC(2);
    wr8(U, A);                                       /* LFF01 */
    CYC(4);
    wait1();                                         /* falls into WAIT1 */
}

/* WAIT1 ($FF03)
 * Condition codes out: NZVC.
 */
void wait1(void)
{
    CK(0xFF03);
    X = 0x0000;                                      /* LFF03  WAIT ABOUT HALF A SECOND */
    CYC(3);
    do {
        CK(0xFF06);
        hw_wr8(WTCHDG, A);                           /* LFF06 */
        X = (uint16_t)(X + 1);                       /* LFF09 */
        CYC(17);
    } while (X < 0xAC55);                            /* LFF0E  HSEND   */
    A = 0xFF;                                        /* LFF10  TURN LED OFF */
    CYC(2);
    wr8(U, A);                                       /* LFF12 */
    X = 0x0000;                                      /* LFF14  WAIT ANOTHER HALF A SECOND */
    CYC(7);
    do {
        CK(0xFF17);
        hw_wr8(WTCHDG, A);                           /* LFF17 */
        X = (uint16_t)(X + 1);                       /* LFF1A */
        CYC(17);
    } while (X < 0xAC55);                            /* LFF1F  HSEND   */
    CYC(4);
    tmulz(); return;                                 /* LFF21  GO BACK TO BEGINNING OF DIAGNOSTICS */
}

/* DIAGERR ($FF24) - THEN INDICATE AN ERROR
 * Condition codes out: NZVC.
 */
void diagerr(void)
{
    CK(0xFF24);
    A = 0x00;                                        /* LFF24  TURN ALL LEDS ON */
    CYC(2);
    hw_wr8(W_LED1, A);                               /* LFF26 */
    CYC(5);
    hw_wr8(W_LED2, A);                               /* LFF29 */
    CYC(5);
    hw_wr8(W_LED3, A);                               /* LFF2C */
    X = 0x0000;                                      /* LFF2F  WAIT ABOUT 1/4 SECOND */
    CYC(8);
    do {
        CK(0xFF32);
        hw_wr8(WTCHDG, A);                           /* LFF32 */
        X = (uint16_t)(X + 1);                       /* LFF35 */
        CYC(17);
    } while (X < 0x5600);                            /* LFF3A  HSEND   */
    A = 0xFF;                                        /* LFF3C  TURN ALL LEDS OFF */
    CYC(2);
    hw_wr8(W_LED1, A);                               /* LFF3E */
    CYC(5);
    hw_wr8(W_LED2, A);                               /* LFF41 */
    CYC(5);
    hw_wr8(W_LED3, A);                               /* LFF44 */
    X = 0x0000;                                      /* LFF47  WAITR ANOTHER 1/4 SECOND */
    CYC(8);
    do {
        CK(0xFF4A);
        hw_wr8(WTCHDG, A);                           /* LFF4A */
        X = (uint16_t)(X + 1);                       /* LFF4D */
        CYC(17);
    } while (X < 0x5600);                            /* LFF52  HSEND   */
    CYC(4);
    tmulz(); return;                                 /* LFF54  GO BACK TO DIAGNOSTIC LOOP */
}
